const assert = require("node:assert/strict");
const { createUser } = require("./create-user.cjs");
const decode = value => JSON.parse(JSON.stringify(value));
const invalid = [
  null, true, false, 0, -1, 3.5, "", "Ada", [], ["Ada"], {},
  { Name: "Ada" }, { name: null }, { name: true }, { name: false },
  { name: 0 }, { name: 1 }, { name: [] }, { name: {} },
  { name: "" }, { name: " " }, { name: "\t\r\n" },
  { name: "\u00a0\u2003\ufeff" },
  JSON.parse('{"__proto__":{"name":"Ada"}}')
];
const valid = [
  { name: "Ada" }, { name: " Ada " }, { name: "\tAda\n" },
  { name: "0" }, { name: "李" }, { name: "😀" }, { name: "\u0000" },
  { name: "Ada", role: "admin", extra: { nested: true } },
  JSON.parse('{"name":"Ada","__proto__":{"role":"admin"}}')
];
let checks = 0;
for (const value of invalid) {
  const input = decode(value);
  const original = JSON.stringify(input);
  const existing = { name: "Existing" };
  const users = [existing];
  assert.throws(() => createUser(input, users), TypeError);
  assert.equal(users.length, 1);
  assert.strictEqual(users[0], existing);
  assert.equal(JSON.stringify(input), original);
  checks++;
}
for (const value of valid) {
  const input = decode(value);
  const original = JSON.stringify(input);
  const existing = { name: "Existing" };
  const users = [existing];
  const record = createUser(input, users);
  assert.equal(users.length, 2);
  assert.strictEqual(users[0], existing);
  assert.strictEqual(record, users[1]);
  assert.deepEqual(Reflect.ownKeys(record), ["name"]);
  assert.equal(record.name, input.name);
  assert.notStrictEqual(record, input);
  assert.equal(JSON.stringify(input), original);
  checks++;
}
const users = [];
const first = createUser(decode({ name: "One" }), users);
const second = createUser(decode({ name: "Two" }), users);
assert.deepEqual(users, [{ name: "One" }, { name: "Two" }]);
assert.strictEqual(users[0], first);
assert.strictEqual(users[1], second);
assert.notStrictEqual(first, second);
checks++;
console.log(JSON.stringify({ runtime: process.version, invalidCases: invalid.length, validCases: valid.length, sequentialWriteCases: 1, checks, result: "PASS" }));

